// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address unauthorizedCaller, address newOwner) public {
        vm.assume(unauthorizedCaller != address(this));
        vm.assume(unauthorizedCaller != address(c));
        vm.prank(unauthorizedCaller);
        try c.setOwner(newOwner) { } catch { }
        address currentOwner = c.owner();
        assertTrue(currentOwner == address(this));
    }
}
